import type * as React from 'react'

import BranchMultipleSelect from './BranchMultipleSelect'
import BranchSelect from './BranchSelect'
import {useWrapper} from './BranchSelect.hooks'
import type {
  BranchSelectBaseProps,
  WrapperProps,
  BranchMultipleSelectBaseProps,
} from './BranchSelect.types'

export default function BranchSelectContainer(
  props: WrapperProps<BranchSelectBaseProps>,
): React.ReactElement | null {
  const addProps = useWrapper(props)
  return addProps.shouldBeVisible ? <BranchSelect {...props} {...addProps} /> : null
}

export function BranchMultipleSelectContainer(
  props: WrapperProps<BranchMultipleSelectBaseProps>,
): React.ReactElement | null {
  const addProps = useWrapper(props)
  return addProps.shouldBeVisible ? <BranchMultipleSelect {...props} {...addProps} /> : null
}
