import * as React from 'react'
import {useCallback} from 'react'
import {graphql, useFragment, useLazyLoadQuery} from 'react-relay'

import {useAppSelector} from '../../../hooks/react-redux'
import {useRefetchablePreloadedQuery} from '../../../hooks/relay/useRefetchablePreloadedQuery'
import {getBranchesLocator, Policy} from '../../../rest/branches'
import {getBuildType, getProject} from '../../../selectors'
import {isArray} from '../../../utils/guards'
import {subscribeOnBuildTypeEvents, subscribeOnProjectEvents} from '../../../utils/subscriber'
import {BUILD_TYPE_BRANCHES_CHANGED} from '../../../utils/subscriptionEvents'
import {useSequenceLoaderReadyHandler} from '../SequenceLoader/SequenceLoader.hooks'

import type {BranchSelect_branches$key} from './__generated__/BranchSelect_branches.graphql'
import type {BranchSelect_defaultBranchVcsName$key} from './__generated__/BranchSelect_defaultBranchVcsName.graphql'
import type {BranchSelect_hasNonDefaultBranches$key} from './__generated__/BranchSelect_hasNonDefaultBranches.graphql'
import type {BranchSelectBranchExistsQuery} from './__generated__/BranchSelectBranchExistsQuery.graphql'
import {branchesQuery, branchExistsQuery} from './BranchSelect.queries'
import type {AddProps, BaseProps, WrapperProps} from './BranchSelect.types'
import {matches} from './BranchSelect.utils'

const hasNonDefaultBranchesFragment = graphql`
  fragment BranchSelect_hasNonDefaultBranches on Branches {
    branch {
      default
      groupFlag
    }
  }
`
export const useHasNonDefaultBranches = (
  branchesKey: BranchSelect_hasNonDefaultBranches$key | null,
) => {
  const branches = useFragment(hasNonDefaultBranchesFragment, branchesKey)?.branch
  return branches?.some(branch => branch.default !== true && branch.groupFlag !== true) === true
}

const defaultBranchVcsNameFragment = graphql`
  fragment BranchSelect_defaultBranchVcsName on Branches {
    branch {
      name
      default
    }
  }
`

function useDefaultBranchVcsName(branchesKey: BranchSelect_defaultBranchVcsName$key | null) {
  const branches = useFragment(defaultBranchVcsNameFragment, branchesKey)?.branch
  return branches?.find(branch => branch.default)?.name
}

const branchesFragment = graphql`
  fragment BranchSelect_branches on Branches {
    ...BranchSelect_hasNonDefaultBranches
    ...BranchSelect_defaultBranchVcsName
    branch {
      internalName
      name
      default
      active
      groupFlag
      unspecified
    }
  }
`

export function useWrapper<P extends BaseProps>({
  projectOrBuildTypeNode,
  policy,
  selected,
  onLoad,
  branchesQueryRef,
  allowAny,
  ...restProps
}: WrapperProps<P>): AddProps {
  const [{branches: branchesOfProject, branchesOfBuildType}, refetch] =
    useRefetchablePreloadedQuery(branchesQuery, branchesQueryRef)
  const branchesKey: BranchSelect_branches$key | null =
    branchesOfProject ?? branchesOfBuildType ?? null
  const branches = useFragment(branchesFragment, branchesKey)
  const hasNonDefaultBranches = useHasNonDefaultBranches(branches)

  const selectedLocator =
    selected != null &&
    !isArray(selected) &&
    selected.wildcard !== true &&
    policy === Policy.ACTIVE_HISTORY_AND_ACTIVE_VCS_BRANCHES &&
    !allowAny &&
    !branches?.branch?.some(branch => matches(branch, selected))
      ? getBranchesLocator({
          node: projectOrBuildTypeNode,
          policy: Policy.ALL_BRANCHES,
          includeSnapshots: true,
          includeSubprojects: true,
          branch: selected,
          inPath: true,
        })
      : ''

  const projectId =
    projectOrBuildTypeNode?.nodeType === 'project' ? projectOrBuildTypeNode.id : null
  const buildTypeId = projectOrBuildTypeNode?.nodeType === 'bt' ? projectOrBuildTypeNode.id : null
  const {branchExistsInProject, branchExistsInBuildType} =
    useLazyLoadQuery<BranchSelectBranchExistsQuery>(branchExistsQuery, {
      selectedLocator,
      projectLocator: `id:${projectId}`,
      btLocator: `id:${buildTypeId}`,
      checkInProject: projectId != null && Boolean(selectedLocator),
      checkInBuildType: buildTypeId != null && Boolean(selectedLocator),
    })
  const selectedIsKnown = branchExistsInProject ?? branchExistsInBuildType

  const shouldBeVisible =
    hasNonDefaultBranches || (selected != null && !isArray(selected) && selected.default !== true)
  const defaultBranchVcsName = useDefaultBranchVcsName(branches)
  const buildTypeInternalId = useAppSelector(
    state =>
      restProps.buildTypeInternalId ??
      (projectOrBuildTypeNode?.nodeType === 'bt'
        ? getBuildType(state, projectOrBuildTypeNode.id)?.internalId
        : null),
  )
  const projectInternalId = useAppSelector(
    state =>
      restProps.projectInternalId ??
      (projectOrBuildTypeNode?.nodeType === 'project'
        ? getProject(state, projectOrBuildTypeNode.id)?.internalId
        : null),
  )
  const doRefetch = useCallback(() => {
    if (!IS_STORYBOOK) {
      refetch(branchesQueryRef.variables)
    }
  }, [branchesQueryRef.variables, refetch])
  React.useEffect(() => {
    if (buildTypeInternalId != null) {
      return subscribeOnBuildTypeEvents(
        buildTypeInternalId,
        [BUILD_TYPE_BRANCHES_CHANGED],
        doRefetch,
      )
    }

    if (projectInternalId != null) {
      return subscribeOnProjectEvents(projectInternalId, [BUILD_TYPE_BRANCHES_CHANGED], doRefetch)
    }

    return undefined
  }, [buildTypeInternalId, projectInternalId, doRefetch])
  React.useEffect(() => {
    if (onLoad != null) {
      onLoad({
        shouldBeVisible,
        defaultBranchVcsName,
      })
    }
  }, [defaultBranchVcsName, onLoad, shouldBeVisible])
  useSequenceLoaderReadyHandler(true)
  return {
    selectedIsKnown,
    branches: branches?.branch,
    hasNonDefaultBranches,
    shouldBeVisible,
    defaultBranchVcsName,
  }
}
