import Anchor from '@jetbrains/ring-ui-built/components/dropdown/anchor'
import {Type} from '@jetbrains/ring-ui-built/components/list/consts'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import {Policy} from '../../../rest/branches'
import type {Branch} from '../../../services/rest'
import type {BranchItem, RingSelectAnchorProps} from '../../../types'
import {DEFAULT_NAME, parseBranch} from '../../../utils/branchNames'
import {noop} from '../../../utils/empty'
import {notNull} from '../../../utils/guards'
import Tooltip from '../../pages/PipelinesPages/components/Tooltip/Tooltip'
import Badge from '../Badge/Badge'
import Icon from '../Icon/Icon'
import MiddleEllipsis from '../MiddleEllipsis/MiddleEllipsis'
import {hasSelection} from '../Tree/Tree.utils'

import type {BranchSelectBaseProps, Props} from './BranchSelect.types'
import {createGroup, createItem, createSeparator, matches} from './BranchSelect.utils'

import styles from './BranchSelect.module.css'

export const Z_INDEX_INCREMENT = 5
const POPUP_WIDTH = 320
const ActiveBranches = createItem({
  name: '<Active branches>',
  active: true,
  wildcard: true,
})
const AllBranches = createItem({
  name: '<All branches>',
  wildcard: true,
})
const UnspecifiedBranch = createItem({
  name: '<Unspecified branch>',
  unspecified: true,
})
type DefaultProps = {
  hasNonDefaultBranches: boolean
  shouldBeVisible: boolean
  onSelect: (selected: Branch | null | undefined, replace?: boolean) => unknown
  inline: boolean
}
type InnerProps = Props<BranchSelectBaseProps> & DefaultProps

class BranchSelect extends React.PureComponent<InnerProps> {
  static defaultProps: DefaultProps = {
    shouldBeVisible: true,
    hasNonDefaultBranches: true,
    onSelect: noop,
    inline: false,
  }

  newSelected: null | {
    value: BranchItem | null | undefined
  } = null

  componentDidMount() {
    this.resetIfNoBranches()

    if (this.newSelected != null) {
      this.select(this.newSelected.value, true)
      this.newSelected = null
    }
  }

  componentDidUpdate() {
    this.resetIfNoBranches()

    if (this.newSelected != null) {
      this.select(this.newSelected.value, true)
      this.newSelected = null
    }
  }

  handleSelect = (selected: BranchItem | null | undefined) => this.select(selected)
  customAnchor = ({wrapperProps, buttonProps, popup}: RingSelectAnchorProps): React.ReactNode => {
    const {onClick, ...restButtonProps} = buttonProps
    const {
      className,
      old,
      oldFullWidth,
      minimalistic,
      special,
      inline,
      withTooltip,
      isBadge,
      badgeClassName,
    } = this.props
    const {branch} = this.getBranches().selected ?? {}
    const isDefaultSelected = branch?.default === true
    const classes = classNames(className, wrapperProps.className, {
      [styles.old]: old,
      [styles.oldFullWidth]: oldFullWidth,
    })
    const newButtonClasses = classNames(styles.newButton, {
      [styles.defaultSelected]: isDefaultSelected,
    })
    const oldButtonClasses = classNames(styles.oldButton, {
      [styles.minimalisticButton]: minimalistic,
      [styles.specialButton]: special,
      [styles.defaultSelected]: isDefaultSelected && !special,
    })
    const label = isDefaultSelected
      ? `Default branch${branch != null && branch.name !== DEFAULT_NAME ? ` (${branch.name})` : ''}`
      : buttonProps.children

    const onClickWrapper = () => {
      if (onClick != null && !hasSelection()) {
        onClick()
      }
    }

    const anchor = (
      <Anchor
        {...buttonProps}
        inline={inline}
        className={newButtonClasses}
        onClick={isBadge ? undefined : onClickWrapper}
      >
        {withTooltip && typeof label === 'string' ? (
          <Tooltip
            long
            delay={500}
            title={label}
            className={styles.tooltipWrapper}
            selfOverflowOnly
          >
            <SvgIcon icon="branches" className={styles.icon} />
            <MiddleEllipsis className={styles.label} tailLength={10} title={null}>
              {label}
            </MiddleEllipsis>
          </Tooltip>
        ) : (
          <>
            <SvgIcon icon="branches" className={styles.icon} />
            <span className={styles.newLabel}>{label}</span>
          </>
        )}
      </Anchor>
    )

    return (
      <>
        <span {...wrapperProps} className={classes} data-branch-select>
          {old === true ? (
            <button
              type="button"
              {...restButtonProps}
              className={oldButtonClasses}
              onClick={onClickWrapper}
            >
              <span>
                <Icon className={styles.branchIcon} name="branch" />
              </span>
              <span className={styles.oldLabel}>{label}</span>
              <span>
                <Icon
                  className={
                    special === true ? styles.dropdownTriggerSpecial : styles.dropdownTrigger
                  }
                  name={special === true ? 'dropdownTriggerSpecial' : 'dropdownTrigger'}
                />
              </span>
            </button>
          ) : isBadge ? (
            <Badge
              label={'Branch'}
              className={classNames(styles.badge, badgeClassName)}
              clickable
              onClick={onClickWrapper}
            >
              {anchor}
            </Badge>
          ) : (
            anchor
          )}
          {popup}
        </span>
      </>
    )
  }

  select(selected: BranchItem | null | undefined, replace?: boolean) {
    const branch = selected?.branch
    this.props.onSelect(branch?.wildcard === true ? null : branch, replace)
  }

  resetIfNoBranches() {
    const {selected, branches, hasNonDefaultBranches, onSelect} = this.props

    if (selected && branches && !hasNonDefaultBranches) {
      onSelect(null, true)
    }
  }

  getWildCard(): BranchItem | null | undefined {
    const {policy, excludeWildcard} = this.props

    if (excludeWildcard === true) {
      return null
    }

    return policy === Policy.ACTIVE_HISTORY_AND_ACTIVE_VCS_BRANCHES ? ActiveBranches : AllBranches
  }

  getBranches(): {
    branches: ReadonlyArray<BranchItem | null | undefined>
    selected: BranchItem | null | undefined
    disabled?: boolean
  } {
    const {
      branches: branchesAndGroups,
      selected,
      includeUnspecified,
      selectedIsKnown,
      allowAny,
    } = this.props
    const wildcard = this.getWildCard()
    const unspecified = includeUnspecified === true ? UnspecifiedBranch : null

    if (!branchesAndGroups) {
      const selectedItem = createItem(selected)
      return {
        branches: [unspecified, wildcard, selectedItem],
        selected: selectedItem ?? wildcard ?? unspecified,
        disabled: true,
      }
    }

    const groups = branchesAndGroups.filter(branch => branch.groupFlag === true)
    const branches = branchesAndGroups.filter(branch => branch.groupFlag !== true)
    const defaultBranch = branches.find(branch => branch.default === true)
    const nonDefaultBranches = branches.filter(branch => branch.default !== true)
    const activeBranches = nonDefaultBranches.filter(branch => branch.active === true)
    const inactiveBranches = nonDefaultBranches.filter(branch => branch.active !== true)
    const defaultItem = createItem(defaultBranch)
    const branchItems = [
      unspecified,
      wildcard,
      defaultItem != null ? createSeparator('Default') : null,
      defaultItem,
      ...createGroup('Groups', groups),
      ...createGroup('Active', activeBranches),
      ...createGroup('Inactive', inactiveBranches),
    ]
    const defaultSelected = wildcard ?? defaultItem ?? unspecified

    if (!selected) {
      return {
        branches: branchItems,
        selected: defaultSelected,
      }
    }

    if (selected.unspecified === true) {
      return {
        branches: branchItems,
        selected: unspecified,
      }
    }

    const knownBranch = branchesAndGroups.find(branch => matches(branch, selected))

    if (knownBranch) {
      return {
        branches: branchItems,
        selected: createItem(knownBranch),
      }
    } else if ((selectedIsKnown === false || selectedIsKnown == null) && !allowAny) {
      this.newSelected = {
        value: defaultSelected,
      }
      return {
        branches: branchItems,
        selected: defaultSelected,
      }
    } else {
      const selectedItem = createItem(selected)
      return {
        branches: [...branchItems, createSeparator('Unknown'), selectedItem],
        selected: selectedItem,
      }
    }
  }

  render(): React.ReactNode {
    const {className, currentZindex, allowAny} = this.props
    const {branches, selected, disabled} = this.getBranches()
    const data = branches.filter(notNull)
    return (
      <Select
        type={Select.Type.CUSTOM}
        customAnchor={this.customAnchor}
        add={allowAny ? {prefix: 'Use branch'} : undefined}
        onAdd={value => this.props.onSelect(parseBranch(value))}
        compact
        label="Select a branch"
        filter={{
          placeholder: 'Filter branches',
          fn: (item, string) => {
            if (item.rgItemType === Type.SEPARATOR) {
              const successors = data.slice(
                data.findIndex(otherItem => otherItem.key === item.key) + 1,
              )
              const children = successors.slice(
                0,
                successors.findIndex(successor => successor.rgItemType === Type.SEPARATOR),
              )
              return children.some(child => child.label?.toLowerCase().includes(string))
            }
            return item.label?.toLowerCase().includes(string) ?? false
          },
        }}
        selected={selected}
        data={data}
        onSelect={this.handleSelect}
        disabled={disabled}
        className={className}
        popupStyle={
          currentZindex != null
            ? {
                zIndex: currentZindex + Z_INDEX_INCREMENT,
              }
            : undefined
        }
        disableMoveOverflow
        disableScrollToActive
        minWidth={POPUP_WIDTH}
      />
    )
  }
}

export default BranchSelect
